// Grid logic for the map viewer: a JavaScript copy of pakgrid.layout,
// pakgrid.geodesy, pakgrid.ids and pakgrid.boundary. Row and column counts
// come from layout.js and the border from boundary.js (both generated by the
// Python library), and every edge and border flag is computed with the same
// formulas, so the viewer agrees with the database.
// tests/test_viewer_js.py checks this against the Python library.
(function (root) {
  "use strict";

  var SCALE = 1e7;
  var SUB = 5;
  var A = 6378137.0;
  var F = 1 / 298.257223563;
  var E2 = F * (2 - F);
  var DEG = Math.PI / 180;

  // Degrees -> integer units of 1e-7 degree, rounding halves to even like
  // Python's round(). Some edges fall exactly on a half (e.g. 754432812.5).
  function toE7(deg) {
    return roundHalfEven(deg * SCALE);
  }

  // -- Geodesy ------------------------------------------------------------

  function gaussLegendre(n) {
    var nodes = [], weights = [];
    for (var i = 1; i <= n; i++) {
      var x = Math.cos(Math.PI * (i - 0.25) / (n + 0.5)), dp = 0;
      for (var it = 0; it < 100; it++) {
        var p0 = 1, p1 = x;
        for (var k = 2; k <= n; k++) {
          var p2 = ((2 * k - 1) * x * p1 - (k - 1) * p0) / k;
          p0 = p1; p1 = p2;
        }
        dp = n * (x * p1 - p0) / (x * x - 1);
        var dx = p1 / dp;
        x -= dx;
        if (Math.abs(dx) < 1e-16) break;
      }
      nodes.push(x);
      weights.push(2 / ((1 - x * x) * dp * dp));
    }
    return { nodes: nodes, weights: weights };
  }

  var GL = gaussLegendre(16);

  function integrate(fn, a, b) {
    var mid = (a + b) / 2, half = (b - a) / 2, sum = 0;
    for (var i = 0; i < GL.nodes.length; i++) sum += GL.weights[i] * fn(mid + half * GL.nodes[i]);
    return half * sum;
  }

  function areaWeight(phi) {
    var s = Math.sin(phi);
    return Math.cos(phi) / Math.pow(1 - E2 * s * s, 2);
  }

  // Area-weighted mean latitude of a band (slightly south of the midpoint).
  function bandCentroidLat(south, north) {
    var a = south * DEG, b = north * DEG;
    var num = integrate(function (p) { return p * areaWeight(p); }, a, b);
    return num / integrate(areaWeight, a, b) / DEG;
  }

  function metresPerDegree(lat) {
    var phi = lat * DEG, s = Math.sin(phi), w = 1 - E2 * s * s;
    var m = A * (1 - E2) / Math.pow(w, 1.5);
    var n = A / Math.sqrt(w);
    return { lat: m * DEG, lon: n * Math.cos(phi) * DEG };
  }

  // Compass names, as in pakgrid.navigate: 8-point name and 16-point abbreviation.
  var COMPASS_8 = ["North", "North-East", "East", "South-East", "South", "South-West", "West", "North-West"];
  var COMPASS_16 = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
                    "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];

  // Round to the nearest integer, halves to even, like Python's round().
  function roundHalfEven(x) {
    var r = Math.round(x);
    return (r - x === 0.5 && r % 2 !== 0) ? r - 1 : r;
  }

  function compass(bearingDeg) {
    return { name: COMPASS_8[roundHalfEven(bearingDeg / 45) % 8],
             short: COMPASS_16[roundHalfEven(bearingDeg / 22.5) % 16] };
  }

  // Compass bearing in degrees, clockwise from north (0 = N, 90 = E, 180 = S, 270 = W).
  function bearing(east, north) {
    var b = Math.atan2(east, north) / DEG;
    return ((b % 360) + 360) % 360;
  }

  // -- Layout -------------------------------------------------------------

  function Grid(layout) {
    this.data = layout;
    this.bounds = layout.bounds;
    this.mid = layout.midlines;
    this.quadrants = layout.quadrants.map(function (q) {
      var b = q.bounds, n5 = SUB * q.nrows, lats = [];
      for (var i = 0; i <= n5; i++) lats.push(toE7(i === n5 ? b.north : b.south + (b.north - b.south) * i / n5));
      return {
        q: q.q, code: q.code, name: q.name, south: b.south, north: b.north, west: b.west, east: b.east,
        nrows: q.nrows, ncols: q.ncols, ncells: q.ncells, areaKm2: q.area_km2,
        latE7: lats, westE7: toE7(b.west), eastE7: toE7(b.east)
      };
    });
    this.E7 = {
      south: toE7(this.bounds.south), north: toE7(this.bounds.north),
      west: toE7(this.bounds.west), east: toE7(this.bounds.east),
      midLat: toE7(this.mid.lat), midLon: toE7(this.mid.lon)
    };
  }

  function fineLat(ql, i) {
    var n5 = SUB * ql.nrows;
    return i === n5 ? ql.north : ql.south + (ql.north - ql.south) * i / n5;
  }

  function fineLon(ql, row, j) {
    var m5 = SUB * ql.ncols[row];
    return j === m5 ? ql.east : ql.west + (ql.east - ql.west) * j / m5;
  }

  function bisectRight(arr, x) {
    var lo = 0, hi = arr.length;
    while (lo < hi) {
      var mid = (lo + hi) >> 1;
      if (x < arr[mid]) hi = mid; else lo = mid + 1;
    }
    return lo;
  }

  // Quadrant, row, column and sub-cell containing a point, or null outside the grid.
  // Same edge rule as the library: points on a line belong to the block north/east of it.
  Grid.prototype.locate = function (lat, lon) {
    var latE7 = toE7(lat), lonE7 = toE7(lon), E = this.E7;
    if (!(latE7 >= E.south && latE7 <= E.north && lonE7 >= E.west && lonE7 <= E.east)) return null;
    var q = ((lonE7 >= E.midLon) ? 2 : 0) | ((latE7 >= E.midLat) ? 1 : 0);
    var ql = this.quadrants[q];
    var n5 = ql.latE7.length - 1;
    var i = Math.min(Math.max(bisectRight(ql.latE7, latE7) - 1, 0), n5 - 1);
    var row = Math.floor(i / SUB);
    var m5 = SUB * ql.ncols[row];
    var j = Math.min(Math.max(Math.floor((lonE7 - ql.westE7) * m5 / (ql.eastE7 - ql.westE7)), 0), m5 - 1);
    while (j > 0 && lonE7 < toE7(fineLon(ql, row, j))) j--;
    while (j < m5 - 1 && lonE7 >= toE7(fineLon(ql, row, j + 1))) j++;
    return { q: q, row: row, col: Math.floor(j / SUB), subRow: i % SUB, subCol: j % SUB };
  };

  // Boundaries and centroid of a cell (sub == null) or one of its sub-cells.
  Grid.prototype.describe = function (q, row, col, sub) {
    var ql = this.quadrants[q];
    var i0 = row * SUB, j0 = col * SUB, i1 = i0 + SUB, j1 = j0 + SUB;
    if (sub != null) {
      i0 += Math.floor(sub / SUB); j0 += sub % SUB; i1 = i0 + 1; j1 = j0 + 1;
    }
    var s = fineLat(ql, i0), n = fineLat(ql, i1), w = fineLon(ql, row, j0), e = fineLon(ql, row, j1);
    var cid = cellId(q, row, col);
    return {
      level: sub == null ? "cell" : "sub",
      id: sub == null ? cid : subCellId(cid, sub),
      code: sub == null ? cellCode(q, row, col) : subCellCode(q, row, col, sub),
      cellId: cid, cellCode: cellCode(q, row, col), sub: sub,
      bounds: { south: toE7(s) / SCALE, west: toE7(w) / SCALE, north: toE7(n) / SCALE, east: toE7(e) / SCALE },
      centroid: [toE7(bandCentroidLat(s, n)) / SCALE, toE7((w + e) / 2) / SCALE]
    };
  };

  // Cells (or sub-cells) overlapping a lat/lon box, as [south, west, north, east] boxes.
  // Returns null when there would be more than `limit`.
  Grid.prototype.itemsInBox = function (south, west, north, east, level, limit) {
    var u = level === "cell" ? SUB : 1, out = [];
    south = Math.max(south, this.bounds.south); north = Math.min(north, this.bounds.north);
    west = Math.max(west, this.bounds.west); east = Math.min(east, this.bounds.east);
    if (south >= north || west >= east) return out;
    for (var k = 0; k < 4; k++) {
      var ql = this.quadrants[k];
      if (ql.west >= east || ql.east <= west || ql.south >= north || ql.north <= south) continue;
      var nRows = ql.nrows * SUB / u;
      var r0 = Math.max(0, Math.floor((south - ql.south) / (ql.north - ql.south) * nRows));
      var r1 = Math.min(nRows - 1, Math.floor((north - ql.south) / (ql.north - ql.south) * nRows));
      for (var r = r0; r <= r1; r++) {
        var row = Math.floor(r * u / SUB), nCols = ql.ncols[row] * SUB / u;
        var s = fineLat(ql, r * u), n = fineLat(ql, (r + 1) * u);
        var c0 = Math.max(0, Math.floor((west - ql.west) / (ql.east - ql.west) * nCols));
        var c1 = Math.min(nCols - 1, Math.floor((east - ql.west) / (ql.east - ql.west) * nCols));
        for (var c = c0; c <= c1; c++) {
          // [south, west, north, east, quadrant, row, column] (row/column at this level)
          out.push([s, fineLon(ql, row, c * u), n, fineLon(ql, row, (c + 1) * u), k, r, c]);
          if (out.length > limit) return null;
        }
      }
    }
    return out;
  };

  // -- Border flags (same as pakgrid.boundary) ------------------------------

  var OUTSIDE = 0, BORDER = 1, INSIDE = 2, BAND = 100000;
  var FLAG_NAMES = ["outside", "border", "inside"];

  function Boundary(data) {
    this.name = data.name; this.license = data.license; this.attribution = data.attribution;
    this.rings = [];
    var x1 = [], y1 = [], x2 = [], y2 = [], bands = new Map();
    data.rings.forEach(function (flat) {
      var ring = [], x = 0, y = 0;
      for (var i = 0; i < flat.length; i += 2) { x += flat[i]; y += flat[i + 1]; ring.push([x, y]); }
      if (ring.length < 4) return;
      this.rings.push(ring);
      for (var v = 0; v + 1 < ring.length; v++) {
        var ax = ring[v][0], ay = ring[v][1], bx = ring[v + 1][0], by = ring[v + 1][1];
        if (ax === bx && ay === by) continue;
        var k = x1.length;
        x1.push(ax / SCALE); y1.push(ay / SCALE); x2.push(bx / SCALE); y2.push(by / SCALE);
        var b0 = Math.floor((Math.min(ay, by) - 1) / BAND), b1 = Math.floor((Math.max(ay, by) + 1) / BAND);
        for (var b = b0; b <= b1; b++) {
          if (!bands.has(b)) bands.set(b, []);
          bands.get(b).push(k);
        }
      }
    }, this);
    this.x1 = x1; this.y1 = y1; this.x2 = x2; this.y2 = y2; this.bands = bands;
  }

  function latBand(lat) { return Math.floor(Math.trunc(lat * SCALE) / BAND); }

  Boundary.prototype.contains = function (lat, lon) {
    var inside = false, list = this.bands.get(latBand(lat)) || [];
    for (var i = 0; i < list.length; i++) {
      var k = list[i], ya = this.y1[k], yb = this.y2[k];
      if ((ya <= lat) !== (yb <= lat)) {
        if (this.x1[k] + (lat - ya) * (this.x2[k] - this.x1[k]) / (yb - ya) > lon) inside = !inside;
      }
    }
    return inside;
  };

  Boundary.prototype.band = function (south, north) {
    var mid = (south + north) / 2, seen = new Set(), spans = [], crossings = [];
    for (var b = latBand(south); b <= latBand(north); b++) {
      var list = this.bands.get(b) || [];
      for (var i = 0; i < list.length; i++) {
        var k = list[i];
        if (seen.has(k)) continue;
        seen.add(k);
        var ya = this.y1[k], yb = this.y2[k], xa = this.x1[k], xb = this.x2[k];
        var loY = ya <= yb ? ya : yb, hiY = ya <= yb ? yb : ya;
        if (hiY < south || loY > north) continue;
        if (ya === yb) {
          spans.push([Math.min(xa, xb), Math.max(xa, xb)]);
        } else {
          var ys = Math.max(south, loY), yn = Math.min(north, hiY);
          var ps = xa + (ys - ya) * (xb - xa) / (yb - ya), pn = xa + (yn - ya) * (xb - xa) / (yb - ya);
          spans.push([Math.min(ps, pn), Math.max(ps, pn)]);
          if ((ya <= mid) !== (yb <= mid)) crossings.push(xa + (mid - ya) * (xb - xa) / (yb - ya));
        }
      }
    }
    spans.sort(function (p, q) { return p[0] - q[0] || p[1] - q[1]; });
    var touched = [];
    spans.forEach(function (sp) {
      var last = touched[touched.length - 1];
      if (last && sp[0] <= last[1]) { if (sp[1] > last[1]) last[1] = sp[1]; }
      else touched.push([sp[0], sp[1]]);
    });
    crossings.sort(function (p, q) { return p - q; });
    return { touched: touched, crossings: crossings };
  };

  function bisectLeft(arr, x) {
    var lo = 0, hi = arr.length;
    while (lo < hi) { var mid = (lo + hi) >> 1; if (arr[mid] < x) lo = mid + 1; else hi = mid; }
    return lo;
  }

  function rowFlags(band, lons, centres) {
    var n = centres.length, flags = new Uint8Array(n), i, a, b;
    for (i = 0; i + 1 < band.crossings.length; i += 2) {
      a = bisectLeft(centres, band.crossings[i]); b = bisectLeft(centres, band.crossings[i + 1]);
      flags.fill(INSIDE, a, b);
    }
    band.touched.forEach(function (t) {
      a = Math.max(bisectLeft(lons, t[0]) - 1, 0);
      b = Math.min(bisectRight(lons, t[1]) - 1, n - 1);
      if (a <= b) flags.fill(BORDER, a, b + 1);
    });
    return flags;
  }

  // Flags for every sub-cell (5 arrays) and cell of one cell row, cached.
  Grid.prototype.rowFlags = function (boundary, q, row) {
    var key = q * 1024 + row;
    this._flagCache = this._flagCache || new Map();
    if (this._flagCache.has(key)) return this._flagCache.get(key);
    if (this._flagCache.size > 3000) this._flagCache.clear();
    var ql = this.quadrants[q], m5 = SUB * ql.ncols[row], lons = [], centres = [], j, k;
    for (j = 0; j <= m5; j++) lons.push(fineLon(ql, row, j));
    for (j = 0; j < m5; j++) centres.push((lons[j] + lons[j + 1]) / 2);
    var subs = [];
    for (k = 0; k < SUB; k++) {
      subs.push(rowFlags(boundary.band(fineLat(ql, row * SUB + k), fineLat(ql, row * SUB + k + 1)), lons, centres));
    }
    var cells = new Uint8Array(ql.ncols[row]);
    for (var c = 0; c < ql.ncols[row]; c++) {
      var allIn = true, allOut = true;
      for (k = 0; k < SUB; k++) {
        for (j = c * SUB; j < c * SUB + SUB; j++) {
          if (subs[k][j] !== INSIDE) allIn = false;
          if (subs[k][j] !== OUTSIDE) allOut = false;
        }
      }
      cells[c] = allIn ? INSIDE : allOut ? OUTSIDE : BORDER;
    }
    var result = { subs: subs, cells: cells };
    this._flagCache.set(key, result);
    return result;
  };

  // Border flag of a cell (sub == null) or one of its sub-cells.
  Grid.prototype.flag = function (boundary, q, row, col, sub) {
    var f = this.rowFlags(boundary, q, row);
    return sub == null ? f.cells[col] : f.subs[Math.floor(sub / SUB)][col * SUB + (sub % SUB)];
  };

  // Metres east/north from a reference point (same as pakgrid.geodesy.local_offset).
  function localOffset(refLat, refLon, lat, lon) {
    var m = metresPerDegree(refLat);
    var east = (lon - refLon) * m.lon, north = (lat - refLat) * m.lat;
    return {
      east: east, north: north, distance: Math.hypot(east, north), bearing: bearing(east, north),
      text: (east >= 0 ? "E" : "W") + Math.round(Math.abs(east)) + " " +
            (north >= 0 ? "N" : "S") + Math.round(Math.abs(north))
    };
  }

  // -- IDs ------------------------------------------------------------------

  function cellId(q, row, col) { return q * 1048576 + row * 1024 + col; }
  function subCellId(cid, sub) { return cid * 32 + sub; }
  function pad(n, w) { var s = String(n); while (s.length < w) s = "0" + s; return s; }
  function quadCode(q) { return (q >> 1) + "" + (q & 1); }
  function cellCode(q, row, col) { return quadCode(q) + "-" + pad(row, 4) + "-" + pad(col, 4); }
  function subCellCode(q, row, col, sub) { return cellCode(q, row, col) + "-" + pad(sub, 2); }

  // Parse 'QQ-RRRR-CCCC' or 'QQ-RRRR-CCCC-SS'; returns null if it is not a cell in the grid.
  Grid.prototype.parseCode = function (code) {
    var m = /^([01]{2})-(\d{4})-(\d{4})(?:-(\d{2}))?$/.exec(String(code).trim());
    if (!m) return null;
    var q = parseInt(m[1], 2), row = +m[2], col = +m[3], sub = m[4] == null ? null : +m[4];
    var ql = this.quadrants[q];
    if (row >= ql.nrows || col >= ql.ncols[row] || (sub != null && sub > 24)) return null;
    return { q: q, row: row, col: col, sub: sub };
  };

  var api = {
    Grid: Grid, Boundary: Boundary, FLAG_NAMES: FLAG_NAMES, OUTSIDE: OUTSIDE, BORDER: BORDER, INSIDE: INSIDE,
    toE7: toE7, bandCentroidLat: bandCentroidLat, metresPerDegree: metresPerDegree,
    localOffset: localOffset, bearing: bearing, compass: compass, cellId: cellId, subCellId: subCellId,
    cellCode: cellCode, subCellCode: subCellCode
  };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.PakGrid = api;
})(this);
